import type { DemoDb } from './seed';

/**
 * Only the three record families created by buildSeedDb() have these exact id
 * shapes. Chat actions, user records and unknown legacy ids are deliberately
 * excluded: an unfamiliar `demo-` prefix is not enough evidence to delete data.
 */
export const isLegacySeedId = (id: string): boolean => /^demo-(?:meal|tx|weight)-[1-9]\d*$/.test(id);

export interface LegacyCleanup {
  db: DemoDb;
  removed: number;
}

/** Pure, idempotent removal of the known records generated by older versions. */
export function withoutLegacySeedRecords(db: DemoDb): LegacyCleanup {
  const meals = db.meals.filter((record) => !isLegacySeedId(record.id));
  const transactions = db.transactions.filter((record) => !isLegacySeedId(record.id));
  const weighIns = db.weighIns.filter((record) => !isLegacySeedId(record.id));
  const removed = db.meals.length - meals.length + db.transactions.length - transactions.length + db.weighIns.length - weighIns.length;
  return removed ? { db: { ...db, meals, transactions, weighIns }, removed } : { db, removed: 0 };
}
